    frame = next((c for c in colors - {bg} if sum(v == c for row in grid for v in row) > 1), None)
    if frame is None:
        return g
    # Find uninterrupted frame runs on the outermost columns.
    runs = []
    for col in (0, w - 1):
        r = 0
        while r < h:
            if grid[r][col] == frame:
                a = r
                while r < h and grid[r][col] == frame:
                    r += 1
                runs.append((a, r, col))
            else:
                r += 1
    if len(runs) < 2:
        return g
    # The two segments bound corresponding panels; order by vertical position.
    runs.sort()
    upper, lower = runs[0], runs[-1]
    ua, ub, uc = upper
    la, lb, lc = lower
    n = min(ub - ua, lb - la)
    # Any non-background, non-frame pixel in the lower segment is a marker.
    marker_color = next((v for row in grid for v in row if v not in (bg, frame)), None)
    if marker_color is None:
        return g
    endpoint = 4
    for r in range(la, la + n):
        marks = [c for c in range(w) if grid[r][c] == marker_color]
        if not marks:
            continue
        ur = ua + (r - la)
