    marks_b = any(grid[r][c] == marker_color for r in range(b0, b1) for c in range(1, w - 1))
    if marks_a and not marks_b:
        (u0, u1), (l0, l1) = (b0, b1), (a0, a1)
        upper_col, lower_col = col_b, col_a
    elif marks_a == marks_b:
        return out
    else:
        (u0, u1), (l0, l1) = (a0, a1), (b0, b1)
        upper_col, lower_col = col_a, col_b
    if u0 > l0:
        upper_col, lower_col = lower_col, upper_col
        (u0, u1), (l0, l1) = (l0, l1), (u0, u1)

    for r in range(l0, l1):
        marks = [c for c in range(w) if grid[r][c] == marker_color]
        if not marks:
            continue
        counterpart = u0 + (r - l0)
        for c in range(w):
            if grid[counterpart][c] != frame:
                out[counterpart][c] = marker_color
        for mc in marks:
            if lower_col == 0:
                for c in range(1, mc):
                    out[r][c] = marker_color
                out[r][mc] = 4
            else:
                for c in range(mc + 1, w - 1):
                    out[r][c] = marker_color
                out[r][mc] = 4
    return out

